export function ItemComparison({ item, values = emptyCorrections(), options, correctionState, note = '', noteState, noteDiagnostic, onCorrectionChange = () => {}, onCorrectionSave = () => {}, onNoteChange = () => {}, onNoteSave = () => {}, onJumpToSourceLine, readOnly = false }: { item: AnalysisReviewItem; values?: CorrectionValues; options?: CorrectionOptions; correctionState?: 'idle' | 'saving' | 'saved' | 'error'; note?: string; noteState?: 'idle' | 'saving' | 'saved' | 'error'; noteDiagnostic?: { error_code: string; stage: string; extraction_item_id: string; source_message_id: string; build_sha: string; request_id: string }; onCorrectionChange?: (key: keyof CorrectionValues, value: string) => void; onCorrectionSave?: () => void; onNoteChange?: (value: string) => void; onNoteSave?: () => void; onJumpToSourceLine: (line: number) => void; readOnly?: boolean }) {
  const corrected = Object.values(values).some(Boolean), issueBadges = reviewIssueBadges(item.review_issues || []), productIssueBadges = productMetadataIssueBadges(item.review_issues || []), lineSpan = item.gemini.span || '', line = sourceLine(lineSpan);
  return <article className={readOnly ? 'item-comparison item-comparison--readonly' : 'item-comparison'}><div className="item-head-grid"><h3>Gemini抽出</h3><div><h3>システム最終結果</h3><span className="inline-badges">{issueBadges.map((badge) => <StatusBadge key={badge.id} label={badge.label} tone={badge.tone} />)}</span></div>{!readOnly && <div><h3>手動修正</h3><span className={`badge ${corrected ? 'badge-warning' : 'badge-neutral'}`}>{corrected ? '手動修正あり' : '未修正'}</span></div>}</div><div className="aligned-fields">{fieldOrder.map(([key, label], index) => <React.Fragment key={key}><div className="comparison-field"><b>{label}</b><span>{rawValue(item.gemini[key])}</span></div><div className="comparison-field system-field"><b>{label}</b><FinalSystemValue item={item} keyName={key} /></div>{!readOnly && <div className="comparison-field manual-field"><b>{label}</b><ManualInput values={values} field={correctionFields[index]} options={options} onChange={onCorrectionChange} /></div>}</React.Fragment>)}</div><div className="item-extra-grid"><div className="comparison-extra"><ComparisonMetadataRow label="原文位置" value={line ? <button className="line-jump" type="button" onClick={() => onJumpToSourceLine(line)}>{lineSpan}</button> : rawValue(lineSpan)} /></div><div className="system-extra"><ComparisonMetadataRow label="商品ID" value={item.system.product_id || '未解決'} badges={productIssueBadges} /><ComparisonMetadataRow label="販売状況" value={item.system.status || '未解決'} /></div>{!readOnly && <div className="manual-actions"><label htmlFor={`note-${item.extraction_item_id}`}>あなたのメモ</label><textarea id={`note-${item.extraction_item_id}`} value={note} maxLength={2000} onChange={(event) => onNoteChange(event.target.value)} /><div><button type="button" disabled={true} onClick={onCorrectionSave}>{correctionState === 'saving' ? '保存中…' : '修正内容を保存'}</button><button type="button" disabled={true} onClick={onNoteSave}>{noteState === 'saving' ? '保存中…' : 'メモを保存'}</button></div>{correctionState === 'saved' && <span