fetchReport = async () => {
    setLoading(true);
    setError("");
    try {
      const res = await api.get<ParallelReportResponse>(
        "/tcg/parallel-report"
      );
      setReport(res);
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      setError(`レポート取得失敗: ${msg}`);
    } finally {
      setLoading(false);
    }
  }

submitType = async (e: FormEvent) => {
    e.preventDefault();
    setError("");
    try {
      // QA 2026-05-31: code は送らない（backend が自動採番）。名称のみ入力。
      await api.post("/super-admin/tcg/types", {
        name_ja: typeForm.name_ja.trim(),
        name_en: typeForm.name_en.trim() || null,
        sort_order: 100,
        is_active: true,
      });
      setTypeForm(emptyType);
      await loadTypes();
    } catch (err) {
      setError(err instanceof Error ? err.message : t("common.saveError"));
    }
  }

removeType = async (id: number) => {
    setError("");
    try {
      await api.delete(`/super-admin/tcg/types/${id}`);
      await loadTypes();
    } catch (e) {
      // 使用中(409)などはメッセージを表示
      setError(e instanceof Error ? e.message : t("common.deleteError"));
    }
  }

submit = async (e: FormEvent) => {
    e.preventDefault();
    setError("");
    const payload = {
      ...form,
      release_date: form.release_date || null,
      name_en: form.name_en || null,
      category: form.category || null,
    };
    try {
      if (editId) {
        await api.patch(`/super-admin/tcg/series/${editId}`, payload);
      } else {
        await api.post("/super-admin/tcg/series", payload);
      }
      setEditId(null);
      setForm({ ...emptySeries, tcg_type: filter });
      await load(filter);
    } catch (err) {
      setError(err instanceof Error ? err.message : t("common.saveError"));
    }
  }

startEdit = (s: TcgSeries) => {
    setEditId(s.id);
    setForm({
      tcg_type: s.tcg_type,
      series_code: s.series_code,
      name_ja: s.name_ja,
      name_en: s.name_en || "",
      release_date: s.release_date || "",
      category: s.category || "",
    });
  }

